sql:
INSERT INTO customers (first_name, last_name, email, signup_date, loyalty_points, is_active)
VALUES ('Ava', 'Morgan', 'ava.morgan.bench1001@example.invalid', CURRENT_TIMESTAMP, 0, TRUE)
RETURNING customer_id, first_name, last_name, email;

INSERT INTO customers (first_name, last_name, email, signup_date, loyalty_points, is_active)
VALUES ('Noah', 'Bennett', 'noah.bennett.bench1002@example.invalid', CURRENT_TIMESTAMP, 25, TRUE)
RETURNING customer_id, first_name, last_name, email;

UPDATE customers SET segment = 'VIP'
WHERE email = 'ava.morgan.bench1001@example.invalid'
RETURNING customer_id, email, segment;

UPDATE customers SET loyalty_points = 1500
WHERE email = 'ava.morgan.bench1001@example.invalid'
RETURNING customer_id, email, loyalty_points;

UPDATE customers SET city = 'Shiraz'
WHERE email = 'noah.bennett.bench1002@example.invalid'
RETURNING customer_id, email, city;

UPDATE customers SET is_active = FALSE
WHERE email = 'noah.bennett.bench1002@example.invalid'
RETURNING customer_id, email, is_active;

UPDATE products SET price = 44.99
WHERE sku = 'BENCH-SKU-1003'
RETURNING product_id, sku, price;

UPDATE products SET category = 'Accessories'
WHERE sku = 'BENCH-SKU-1003'
RETURNING product_id, sku, category;

UPDATE products SET is_active = FALSE
WHERE sku = 'BENCH-SKU-1004'
RETURNING product_id, sku, is_active;

UPDATE products SET popularity_score = 88.5
WHERE sku = 'BENCH-SKU-1003'
RETURNING product_id, sku, popularity_score;

UPDATE product_variants SET stock_quantity = 30
WHERE variant_sku = 'BENCH-VAR-UPDATE-1010'
RETURNING variant_id, variant_sku, stock_quantity;

UPDATE product_variants SET price_adjustment = 2.50
WHERE variant_sku = 'BENCH-VAR-UPDATE-1011'
RETURNING variant_id, variant_sku, price_adjustment;

UPDATE product_variants SET is_active = FALSE
WHERE variant_sku = 'BENCH-VAR-UPDATE-1012'
RETURNING variant_id, variant_sku, is_active;

UPDATE orders SET status = 'cancelled'
WHERE order_id = -1012
RETURNING order_id, status;

UPDATE orders SET payment_method = 'benchmark_test'
WHERE order_id = -1013
RETURNING order_id, payment_method;

UPDATE order_items SET quantity = 2
WHERE order_item_id = -1014
RETURNING order_item_id, quantity;

UPDATE reviews SET verified_purchase = TRUE
WHERE review_id = -1015
RETURNING review_id, verified_purchase;

UPDATE customer_events SET source = 'benchmark_updated'
WHERE event_id = -1016
RETURNING event_id, source;

UPDATE inventory_events SET reason = 'benchmark_reviewed'
WHERE inventory_event_id = -1017
RETURNING inventory_event_id, reason;

DELETE FROM customer_events
WHERE event_type = 'search' AND source = 'benchmark_delete_1045'
RETURNING event_id, customer_id, event_type, source;

DELETE FROM reviews
WHERE review_title = 'Benchmark Delete Candidate 1046'
RETURNING review_id, customer_id, product_id, review_title;

DELETE FROM wishlist
WHERE customer_id = -1049 AND added_at = TIMESTAMP '2001-01-01 00:00:00'
RETURNING wishlist_id, customer_id, product_id, added_at;
